insert into public.pulse_challenge_templates (id, code, title, description, category, difficulty, points, answer_type, options, scoring_rule, required_facts, active, priority, cooldown_days, tags)
select 'cht_' || lower(code), code, title, description, category, difficulty, points, "answerType", options, rule, array['home_score','away_score']::text[], true, priority, cooldown, array(select jsonb_array_elements_text(tags))
from jsonb_to_recordset($json$[{"code":"LOSER_LTE_3","title":"¿El perdedor se queda en 3 o menos?","description":"Se corrige con el marcador final.","category":"defensiva","difficulty":"easy","points":2,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"loser_lte","n":3},"priority":0,"cooldown":2,"tags":["defensiva"]},{"code":"LOSER_GTE_3","title":"¿El perdedor anotará 3 o más?","description":"Se corrige con el marcador final.","category":"marcador","difficulty":"medium","points":4,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"loser_gte","n":3},"priority":0,"cooldown":2,"tags":["marcador"]},{"code":"LOSER_GTE_4","title":"¿El que pierda igual anota 4 o más?","description":"Se corrige con el marcador final.","category":"marcador","difficulty":"hard","points":6,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"loser_gte","n":4},"priority":0,"cooldown":2,"tags":["marcador"]},{"code":"LOSER_GTE_5","title":"¿El perdedor llegará a 5 o más?","description":"Se corrige con el marcador final.","category":"ofensiva","difficulty":"expert","points":8,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"loser_gte","n":5},"priority":0,"cooldown":2,"tags":["ofensiva"]}]$json$::jsonb) as t(code text, title text, description text, category text, difficulty text, points int, "answerType" text, options jsonb, rule jsonb, priority int, cooldown int, tags jsonb)
on conflict (code) do nothing;